// A swirl: a barrel with a few big waves around it, which turn on
// their way up and carry fine ribs. Units: mm.

const n_tau = PI * 2;
const n_height = 115;
const n_its_layer = 140;
// Many corners: each rib needs about 9 of them to look round.
const n_its_corner = 555;
const n_height_cone = 10;
// A low dome closes the top.
const n_height_dome = 11;
const n_overhang_dome = 60;

// The barrel: its radius at the bottom, at its widest and at the
// top, and how high up it is widest, from 0 to 1.
const n_radius_bottom = 35;
const n_radius_belly = 46;
const n_radius_top = 37;
const n_belly_at = 0.44;

// The big waves: how many, and how far they go in and out.
const n_its_wave = 5;
const n_amp_wave = 6;
// How much each wave leans over to one side, like a breaking
// wave: 0 is even, 0.6 leans a lot.
const n_lean_wave = 0.5;

// The ribs: how many on each wave, and how deep.
const n_its_rib_per_wave = 8;
const n_amp_rib = 1.1;

// How far everything turns on its way up: 1 is a full turn.
const n_twist = 0.6;
// On top of that it swings back and forth by this much, which
// bends the waves into an S.
const n_sway = 0.04;

function f_o_p(n_it_layer_nor, n_it_corner_nor) {
    const n_t = n_it_layer_nor;

    // The barrel's outline: smooth from the bottom to the belly,
    // and from the belly to the top.
    let n_r = n_t < n_belly_at
        ? mix(n_radius_bottom, n_radius_belly,
            sin(n_t / n_belly_at * PI / 2))
        : mix(n_radius_top, n_radius_belly,
            cos((n_t - n_belly_at) / (1 - n_belly_at) * PI / 2));

    // Where this corner is on the pattern, after the turn.
    const n_turn = n_twist * n_t + n_sway * sin(n_t * n_tau);
    const n_around = (n_it_corner_nor - n_turn) * n_tau;

    // The big waves, leaning to one side.
    const n_phase = n_around * n_its_wave;
    n_r += sin(n_phase + n_lean_wave * sin(n_phase)) * n_amp_wave;

    // The ribs: round on the outside, with a sharp groove between.
    n_r += abs(sin(n_around * n_its_wave * n_its_rib_per_wave / 2))
        * n_amp_rib;

    return {
        n_x: sin(n_it_corner_nor * n_tau) * n_r,
        n_y: cos(n_it_corner_nor * n_tau) * n_r,
        n_z: o_thread.n_z + n_height_cone + n_t * n_height,
    };
}

return {
    n_its_layer, n_its_corner, f_o_p,
};
